      if(/^(?:stretch|stretchs|stretches|stretching|stretched|stretchy|stretchess|stretchin|stretcc?h(?:es|ing)?|strec?h(?:es|ing)?|strech(?:es|ing)?|strecth(?:es|ing)?|stret+ch(?:es|ing)?|stret+ching+)$/.test(t))return 'stretch';
