    const visual=youtube||mode==='image'||mode==='video';
    const mediaCue=/\b(?:youtube|youtubers?|watch|watching|videos?|clips?|shorts?|reels?|photos?|pics?|images?|gallery|galleries|pictures?|haul|try on|roleplay|relaxing sounds|whispering|compilation|see|show me|look at)\b/.test(x);
