  function restrictedYouTubeVideoTitleV146(href,title) {
    try {
      const u=new URL(href);
      if(!/(^|\.)(?:youtube\.com|youtube-nocookie\.com)$/.test(u.hostname.toLowerCase()) &&
         u.hostname.toLowerCase()!=='youtu.be')return false;
      const p=u.pathname.toLowerCase();
      if(!(/^\/(?:watch|shorts\/|live\/|embed\/|clip\/)/.test(p)||u.hostname.toLowerCase()==='youtu.be'))return false;
      const t=String(title||'').replace(/\s*(?:-|\|)\s*YouTube\s*$/i,'').trim();
      if(!t || /^(?:youtube|watch|shorts|loading)$/i.test(t))return false;
      return isBlocked(t,'video','youtube-title');
    }catch{return false;}
  }


